import tempfile
import torch
import torch.nn as nn
from topologies import Trainer, build, synth
root = tempfile.mkdtemp()
@synth.generator
def samples(ctx):
    features = torch.randn(4, generator=ctx.rng.torch)
    mask = torch.zeros((1, 4, 4))
    mask[0, 1, :] = 1
    return {"inputs": synth.Tensor(features), "targets": synth.Tensor(mask)}
class SegmentationModel(nn.Module):
    def __init__(self):
        super().__init__()
        self.network = build("mlp", "tiny", in_features=4, out_features=16)
    def forward(self, inputs):
        return torch.sigmoid(self.network(inputs)).reshape(-1, 1, 4, 4)
ds = synth.Spec("cldice-segmentation", generator=samples, size=8, splits={"train": 1.0}, seed=11, root=root, monitor="none").run()
train = ds.for_recipe("regression", split="train", input_field="inputs", target_field="targets", preserve_shape=True)
model = SegmentationModel()
trainer = Trainer(model, train, recipe="regression", recipe_config={"loss": "cldice-loss", "loss_kwargs": {"iterations": 1, "epsilon": 0.01}}, batch_size=4, max_epochs=1, device="cpu")
trainer.fit()
